const isSpace = (char: string, newlineOk: boolean): boolean =>
  char === ' ' ||
  char === '\t' ||
  char === '#' ||
  (newlineOk && (char === '\r' || char === '\n'));

export const parseSpace = (src: string, pos: number, newlineOk: boolean): number => {
  while (isSpace(charAt(src, pos), newlineOk)) {
