import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import GBNF, { InputParseError, ruleToDict } from 'gbnf';

const cases = JSON.parse(readFileSync('/tmp/parity/cases.json', 'utf8'));
const expected = JSON.parse(readFileSync('/tmp/parity/python.json', 'utf8'));

const asError = (e: unknown) => {
  const err = e as Error;
  const out: Record<string, string> = {
    name: err.name === 'Error' ? 'Exception' : err.name,
    message: err.message,
  };
  if (e instanceof InputParseError) {
    out.errorForMostRecentInput = e.errorForMostRecentInput;
  }
  return { error: out };
};

const run = (grammar: string, inputs: string[]) => {
  const steps: unknown[] = [];
  let state;
  try {
    state = GBNF(grammar);
  } catch (e) {
    return { steps: [asError(e)] };
  }
  steps.push({ rules: [...state].map((rule) => ruleToDict(rule)) });
  for (const chunk of inputs) {
    try {
      state = state.add(chunk);
    } catch (e) {
      steps.push(asError(e));
      break;
    }
    steps.push({ rules: [...state].map((rule) => ruleToDict(rule)) });
  }
  return { steps };
};

describe('parity with the python reference', () => {
  test.for(cases.map((c: never, i: number) => [i, c] as const))(
    'case %i',
    ([i, c]: [number, { grammar: string; inputs: string[] }]) => {
      expect(run(c.grammar, c.inputs)).toEqual(expected[i]);
    }
  );
});

